import{X as e,Y as t,lt as n,n as r}from"./chunks/framework.CEVcUq38.js";var i=JSON.parse(`{"title":"Référence des types de graphiques","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/chart-types.md","filePath":"fr/guide/chart-types.md"}`),a={name:`fr/guide/chart-types.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="reference-des-types-de-graphiques" tabindex="-1">Référence des types de graphiques <a class="header-anchor" href="#reference-des-types-de-graphiques" aria-label="Permalink to “Référence des types de graphiques”">​</a></h1><p>Comment construire chaque type de graphique. Ce sont tous des objets du même genre : des axes, un ou plusieurs rendus, parfois une transformation qui dérive une série, parfois des annotations. La <a href="../../fr/examples/gallery">galerie</a> montre chacun d&#39;eux, avec son code.</p><table tabindex="0"><thead><tr><th>Type de graphique</th><th>Comment</th></tr></thead><tbody><tr><td>Ligne, aire, nuage de points</td><td><code>D3PLineRenderer</code>, <code>D3PAreaRenderer</code>, <code>D3PScatterRenderer</code></td></tr><tr><td>Spline, marches</td><td><code>style.curve</code> : <code>monotone</code>, <code>step</code>, <code>stepBefore</code>, <code>stepAfter</code>, <code>basis</code>, <code>cardinal</code>, <code>catmullRom</code>, <code>natural</code></td></tr><tr><td>Trous dans les données</td><td><code>style.gaps: &#39;break&#39;</code> (par défaut <code>connect</code>)</td></tr><tr><td>Colonnes</td><td><code>D3PBarRenderer</code> sur un axe bande ; <code>count</code> et <code>index</code> placent plusieurs séries côte à côte</td></tr><tr><td>Barres horizontales</td><td><code>D3PBarRenderer</code> avec <code>orientation: &#39;horizontal&#39;</code>, catégories sur un axe bande à gauche</td></tr><tr><td>Empilé, 100 %, streamgraph</td><td><code>D3PStack</code> avec <code>offset: &#39;none&#39; | &#39;expand&#39; | &#39;silhouette&#39; | &#39;wiggle&#39;</code> (et <code>order</code>), dessiné par des aires ou des barres</td></tr><tr><td>Aire de plage</td><td>une série avec <code>columns: [&#39;x&#39;, &#39;high&#39;, &#39;low&#39;]</code> et <code>D3PAreaRenderer({ props: { base: &#39;low&#39; } })</code></td></tr><tr><td>Colonne de plage, chronologie</td><td><code>D3PBarRenderer</code> avec <code>base: &#39;start&#39;</code> (et <code>orientation: &#39;horizontal&#39;</code> pour une chronologie)</td></tr><tr><td>Histogramme</td><td><code>D3PHistogram</code> (ou <code>d3pHistogram</code>) qui alimente <code>D3PBarRenderer</code> : les barres prennent leur largeur aux bornes des classes</td></tr><tr><td>Cascade (waterfall)</td><td><code>D3PWaterfall</code> qui alimente <code>D3PBarRenderer</code> avec <code>style.colorBy: &#39;kind&#39;</code></td></tr><tr><td>Sucettes</td><td><code>D3PBarRenderer</code> avec <code>style.shape: &#39;lollipop&#39;</code></td></tr><tr><td>Chandeliers</td><td><code>D3PCandlestickRenderer</code> sur une série avec <code>open</code>, <code>high</code>, <code>low</code>, <code>close</code></td></tr><tr><td>Boîtes à moustaches</td><td><code>D3PBoxPlotRenderer</code> ; <code>d3pBoxPlotRows(groupes)</code> calcule quartiles, moustaches et valeurs aberrantes depuis des échantillons bruts</td></tr><tr><td>Haltères (dumbbell)</td><td><code>D3PDumbbellRenderer</code> sur une série avec <code>start</code> et <code>end</code></td></tr><tr><td>Bulles</td><td><code>D3PBubbleRenderer</code> sur une série avec une colonne <code>size</code></td></tr><tr><td>Carte de chaleur</td><td><code>D3PHeatmapRenderer</code> avec une <code>D3PColorScale</code>, et une <code>D3PColorLegend</code></td></tr><tr><td>Camembert, anneau, demi-anneau</td><td><code>D3PPieRenderer</code> dans un <code>D3PPolarSystem</code> (<code>innerRadius</code>, <code>sweep</code>)</td></tr><tr><td>Radar</td><td>axes polaires avec <code>D3PRadarAngleAxisRenderer</code>, et lignes ou aires avec <code>curve: &#39;straight&#39;</code> et <code>closed: true</code></td></tr><tr><td>Aire polaire (rose)</td><td><code>D3PBarRenderer</code> sur des axes polaires, catégories sur l&#39;angle</td></tr><tr><td>Barres radiales, jauge</td><td><code>D3PBarRenderer</code> avec <code>orientation: &#39;horizontal&#39;</code> sur des axes polaires, catégories sur le rayon ; <code>sweep: 180</code> pour une jauge</td></tr><tr><td>Entonnoir (funnel)</td><td><code>D3PFunnelRenderer</code> (sans axes)</td></tr><tr><td>Pentes (slope)</td><td>lignes sur un axe point avec une catégorie vide à chaque bout</td></tr><tr><td>Sparkline</td><td><code>d3pSparkline({ container, data, type })</code></td></tr><tr><td>Annotations</td><td><code>D3PAnnotationLine</code>, <code>D3PAnnotationBand</code>, <code>D3PAnnotationPoint</code>, <code>D3PAnnotationText</code></td></tr></tbody></table><p>Non inclus : treemap, sunburst et icicle (ils demandent des données hiérarchiques), violin et raincloud, waffle, unit et beeswarm, et les fonctions multi-graphiques (trellis, crossfilter, sélections liées).</p><h2 id="donnees" tabindex="-1">Données <a class="header-anchor" href="#donnees" aria-label="Permalink to “Données”">​</a></h2><p>Une série est une liste de points ; un point est <code>[x, valeur, ...autres]</code>. Les colonnes ont des noms, et un rendu demande celles dont il a besoin :</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// deux colonnes, comme toujours</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> D3PSeries</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;cpu&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, data: [[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]] })</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// plusieurs colonnes : un chandelier a besoin de open, high, low et close</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> D3PSeries</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;AAPL&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  columns: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;x&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;open&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;high&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;low&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;close&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  primary: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;close&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,          </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// ce que veut dire « la valeur » (marqueur d&#39;infobulle, légende, domaine par défaut)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  data: rows,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><p><code>primary</code> vaut par défaut la deuxième colonne. Un rendu qui a besoin de colonnes absentes de la série la refuse à l&#39;attachement, en disant lesquelles.</p><p>Entrées acceptées, détectées sur la première ligne :</p><table tabindex="0"><thead><tr><th>Entrée</th><th>Exemple</th></tr></thead><tbody><tr><td>nombres, tableaux typés</td><td><code>[3, 5, 2]</code> : <code>x</code> est l&#39;index (deux colonnes seulement)</td></tr><tr><td>lignes positionnelles</td><td><code>[[0, 3], [&#39;a&#39;, 5]]</code>, dans l&#39;ordre de <code>columns</code></td></tr><tr><td>lignes objet</td><td><code>[{ x: 0, y: 3 }]</code>, ou d&#39;autres clés et des fonctions avec <code>fields: { x: &#39;t&#39;, y: (ligne) =&gt; ligne.v }</code></td></tr><tr><td>par colonnes</td><td><code>{ x: [0, 1], y: [3, 5] }</code></td></tr><tr><td>tout itérable de ces formes</td><td>un <code>Set</code>, un générateur, <code>Map.entries()</code></td></tr></tbody></table><h3 id="ajuster-les-domaines" tabindex="-1">Ajuster les domaines <a class="header-anchor" href="#ajuster-les-domaines" aria-label="Permalink to “Ajuster les domaines”">​</a></h3><p><code>D3PAutoDomain.linkSeries(serie, [dx, dy])</code> ajuste le second domaine à <strong>toutes les colonnes de valeur</strong> (les plus bas et les plus hauts d&#39;un chandelier, pas seulement sa clôture). Les colonnes qui ne sont pas des positions (<code>size</code>, <code>value</code>, <code>kind</code>, <code>color</code>, <code>label</code>) sont laissées de côté ; <code>domainColumns</code> le modifie. Pour associer les colonnes une à une, utilisez les noms : <code>linkSeries(serie, { x: dx, value: couleurs.domain })</code>.</p><h3 id="series-derivees" tabindex="-1">Séries dérivées <a class="header-anchor" href="#series-derivees" aria-label="Permalink to “Séries dérivées”">​</a></h3><p>Une transformation dérive des séries d&#39;autres séries et les tient à jour. Les séries dérivées sont des séries ordinaires qui portent des colonnes supplémentaires pour les rendus :</p><table tabindex="0"><thead><tr><th>Transformation</th><th>Colonnes dérivées</th></tr></thead><tbody><tr><td><code>D3PStack</code></td><td><code>x</code>, <code>y</code> (haut de la couche), <code>y0</code> (sa base), <code>value</code> (la valeur d&#39;origine, que montre l&#39;infobulle)</td></tr><tr><td><code>D3PWaterfall</code></td><td><code>x</code>, <code>y</code>, <code>y0</code>, <code>value</code>, <code>kind</code> (<code>up</code>, <code>down</code>, <code>total</code>)</td></tr><tr><td><code>D3PHistogram</code></td><td><code>x</code>, <code>y</code> (effectif), <code>x0</code>, <code>x1</code> (les bornes de la classe)</td></tr></tbody></table><p>Les aires et les barres lisent d&#39;elles-mêmes une colonne <code>y0</code>, ou celle que nomme <code>base</code>.</p><h2 id="systemes-de-coordonnees" tabindex="-1">Systèmes de coordonnées <a class="header-anchor" href="#systemes-de-coordonnees" aria-label="Permalink to “Systèmes de coordonnées”">​</a></h2><p>Barres, aires, lignes, nuages, bulles et cartes de chaleur dessinent dans <strong>n&#39;importe quel</strong> système de coordonnées : des rectangles en cartésien, des arcs en polaire, si bien que le même rendu donne un graphique en colonnes ou une aire polaire. Chandeliers, boîtes à moustaches et haltères dessinent des rectangles et des lignes et sont cartésiens seulement ; les camemberts sont polaires seulement ; les entonnoirs n&#39;utilisent aucun système. Un rendu qui ne gère pas un système le dit.</p><p>Un <a href="../../fr/guide/concepts#systemes-de-coordonnees">système polaire</a> peut couvrir une partie d&#39;un cercle (<code>sweep</code>), être un anneau (<code>innerRadius</code>), commencer n&#39;importe où (<code>startAngle</code>) et être déplacé (<code>shift</code>, en fractions du rayon, pour centrer un demi-disque).</p>`,19)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};